import * as React from "react";
import { render, fireEvent, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import * as stories from "./Modal.stories";
import Modal from ".";
import Button from "../Button";

const { Basic } = composeStories(stories) as any;

describe("Modal component", () => {
  ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(
      <Modal open data-testid="modal">
        Text
      </Modal>
    );

    expect(screen.getByRole("presentation")).toHaveAttribute(
      "data-testid",
      "modal"
    );
  });

  it("manage body properties", () => {
    const ParentModal = () => {
      const [open, setOpen] = React.useState(false);
      const handleOpen = () => {
        setOpen(true);
      };
      const handleClose = () => {
        setOpen(false);
      };
      return (
        <div>
          <Button onClick={handleOpen}>Open modal</Button>
          <Modal open={open} onClose={handleClose}>
            <Button onClick={handleClose} style={{ margin: 20 }}>
              Close modal
            </Button>
            <ChildModal />
          </Modal>
        </div>
      );
    };

    const ChildModal = () => {
      const [open, setOpen] = React.useState(false);
      const handleOpen = () => {
        setOpen(true);
      };
      const handleClose = () => {
        setOpen(false);
      };
      return (
        <React.Fragment>
          <Button onClick={handleOpen} variant="primary">
            Confirm child
          </Button>
          <Modal open={open} onClose={handleClose}>
            <Button onClick={handleClose} style={{ margin: 20 }}>
              Close child
            </Button>
            <GrandChildModal />
          </Modal>
        </React.Fragment>
      );
    };

    const GrandChildModal = () => {
      const [open, setOpen] = React.useState(false);
      const handleOpen = () => {
        setOpen(true);
      };
      const handleClose = () => {
        setOpen(false);
      };
      return (
        <React.Fragment>
          <Button onClick={handleOpen} variant="primary">
            Confirm grand child
          </Button>
          <Modal open={open} onClose={handleClose}>
            <Button onClick={handleClose} style={{ margin: 20 }}>
              Close grand child
            </Button>
          </Modal>
        </React.Fragment>
      );
    };

    const { baseElement } = render(<ParentModal />);
    const elt = baseElement as HTMLElement;
    elt.style.overflow = "none";
    elt.style.paddingRight = "16px";

    fireEvent.click(screen.getByRole("button", { name: /Open modal/ }));
    expect(screen.getByRole("presentation")).toBeInTheDocument();
    expect(elt).toHaveStyle("overflow:hidden");
    expect(elt).toHaveStyle("padding-right:32px");
    expect(elt.style.getPropertyPriority("padding-right")).toEqual("important");

    fireEvent.click(screen.getByRole("button", { name: /Confirm child/ }));
    expect(elt).toHaveStyle("overflow:hidden");

    fireEvent.click(
      screen.getByRole("button", { name: /Confirm grand child/ })
    );
    expect(elt).toHaveStyle("overflow:hidden");

    fireEvent.click(screen.getByRole("button", { name: /Close grand child/ }));
    expect(elt).toHaveStyle("overflow:hidden");

    fireEvent.click(screen.getByRole("button", { name: /Close child/ }));
    expect(elt).toHaveStyle("overflow:hidden");

    fireEvent.click(screen.getByRole("button", { name: /Close modal/ }));
    expect(elt).toHaveStyle("overflow:none");
    expect(elt).toHaveStyle("padding-right:16px");
  });
});
